mapper.select:

SELECT COUNT(*) as count
FROM(


SELECT 
	SHOP_ID ,CODE_NM ,CAUSE ,DATE_FORMAT(INPUT_DATETIME ,'%Y-%m-%d %H:%i:%s') as INPUT_DATETIME,'실패' as STATUS, RUNTIME, ERROR_LOG
FROM CBCI_ERR_REPORT
WHERE 
	CODE_ID in (${selectShop})
	AND INPUT_DATETIME >= #{fromDate}
	AND INPUT_DATETIME <= #{toDate}
	AND CAUSE like #{SCENARIO}


UNION ALL


SELECT
	SHOP_ID, SHOP_NM as CODE_NM, SCHEDULED_NAME as CAUSE, DATE_FORMAT(INPUT_DATE,'%Y-%m-%d %H:%i:%s') as INPUT_DATETIME, '성공' as STATUS, RUNTIME,"-" as ERROR_LOG
FROM CBCI_SCHEDULED_REPORT
WHERE
	SHOP_TYPE in (${selectShop})
	AND INPUT_DATE >= #{fromDate}
	AND INPUT_DATE <= #{toDate}
	AND SCHEDULED_NAME like #{SCENARIO}

ORDER BY INPUT_DATETIME DESC

) RESULT_TB


LIMIT ${LIMIT}

SELECT
	SMS_TITLE,
	SMS_CONTENT
FROM CBCI_SMS_TEMPLATE 
WHERE SMS_KEY = #{SMS_KEY}
AND SMS_CODE = #{SMS_CODE}

SELECT
	@ROWNUM := @ROWNUM + 1 AS RNUM
  , (SELECT CODE_NM FROM CBCI_CODE WHERE CODE_ID = ca.SHOP_TYPE) AS SHOP_NM
  , SHOP_ID
FROM CBCI_ACCOUNT ca, (SELECT @ROWNUM := 0) ROWNUM_TB
WHERE ca.USER_CODE = #{USER_CODE}
